import React, { useState, useEffect } from 'react';
import { useTheme } from '../../contexts/ThemeContext';
import { modelAPI, marketAPI, backtestAPI } from '../../services/api';

export default function Models() {
  const [activeTab, setActiveTab] = useState('svr');
  const [candles, setCandles] = useState([]);
  const [loading, setLoading] = useState(false);
  const [statusMessage, setStatusMessage] = useState('');
  const [backtestResult, setBacktestResult] = useState(null);
  const [modelParams, setModelParams] = useState({
    svr: { C: 1.0, epsilon: 0.1, gamma: 'scale' },
    gpr: { nu: 1.5, length_scale: 1.0 }
  });
  
  // Новые состояния для выбора данных
  const [figi, setFigi] = useState('BBG004730N88'); // SBER
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [availableFigis, setAvailableFigis] = useState([
    { value: 'BBG004730N88', label: 'SBER - Сбербанк' },
    { value: 'BBG004730ZJ9', label: 'GAZP - Газпром' },
    { value: 'BBG00475JZZ6', label: 'LKOH - Лукойл' },
    { value: 'BBG004S681W4', label: 'ROSN - Роснефть' },
    { value: 'BBG004RVFCY3', label: 'MGNT - Магнит' }
  ]);

  const { isDark } = useTheme();

  const modelConfigs = {
    svr: {
      name: 'Метод опорных векторов',
      kernel: 'RBF',
      parameters: [
        { name: 'C', type: 'number', min: 0.1, max: 10, step: 0.1 },
        { name: 'gamma', type: 'select', options: ['scale', 'auto'] },
        { name: 'epsilon', type: 'number', min: 0.01, max: 1, step: 0.01 }
      ]
    },
    gpr: {
      name: 'Гауссовская регрессия', 
      kernel: 'Matérn',
      parameters: [
        { name: 'length_scale', type: 'number', min: 0.1, max: 10, step: 0.1 },
        { name: 'nu', type: 'number', min: 0.5, max: 2.5, step: 0.5 }
      ]
    }
  };

  // Инициализация дат по умолчанию
  useEffect(() => {
    const end = new Date();
    const start = new Date();
    start.setMonth(start.getMonth() - 1); // 1 месяц назад
    
    setEndDate(end.toISOString().split('T')[0]);
    setStartDate(start.toISOString().split('T')[0]);
    
    loadCandles();
  }, []);

  // Загрузка исторических данных с учетом выбранных дат
  const loadCandles = async () => {
    try {
      setStatusMessage('Загрузка исторических данных...');
      
      // В реальном API нужно передавать startDate и endDate
      const response = await marketAPI.loadCandles(figi, startDate, endDate);
      const loadedCandles = response.data.candles || [];
      setCandles(loadedCandles);
      setStatusMessage(`Загружено свечей: ${loadedCandles.length}`);
      
      return loadedCandles;
    } catch (error) {
      console.error('Ошибка загрузки свечей:', error);
      setStatusMessage('❌ Не удалось загрузить свечи');
      return [];
    }
  };

  // Подготовка данных для обучения модели
  const prepareTrainingData = (candlesData) => {
    if (!candlesData || candlesData.length < 10) {
      throw new Error('Недостаточно данных для обучения (нужно минимум 10 свечей)');
    }

    const X = [];
    const y = [];
    const prices = []; // Цены для бэктеста
    
    const lookback = 10;
    
    for (let i = lookback; i < candlesData.length - 1; i++) {
      const features = [];
      
      // Добавляем данные из предыдущих свечей
      for (let j = i - lookback; j < i; j++) {
        const candle = candlesData[j];
        features.push(
          parseFloat(candle.o), // open
          parseFloat(candle.h), // high
          parseFloat(candle.l), // low
          parseFloat(candle.c), // close
          parseFloat(candle.v)  // volume
        );
      }
      
      X.push(features);
      prices.push(parseFloat(candlesData[i].c)); // Текущая цена для бэктеста
      y.push(parseFloat(candlesData[i + 1].c)); // Следующая цена для предсказания
    }
    
    return { X, y, prices };
  };

  // Обучение модели
  const trainModel = async () => {
    try {
      if (candles.length === 0) {
        setStatusMessage('❌ Нет данных для обучения. Сначала загрузите свечи.');
        return;
      }

      setLoading(true);
      setStatusMessage('Подготовка данных и обучение модели...');

      const { X, y } = prepareTrainingData(candles);
      
      console.log(`Подготовлено данных: X=${X.length} samples, y=${y.length} targets`);
      
      if (X.length === 0 || y.length === 0) {
        setStatusMessage('❌ Не удалось подготовить данные для обучения');
        setLoading(false);
        return;
      }

      let response;
      const currentParams = modelParams[activeTab];
      
      if (activeTab === 'svr') {
        response = await modelAPI.trainSVR({
          ...currentParams,
          X: X,
          y: y
        });
      } else if (activeTab === 'gpr') {
        response = await modelAPI.trainGPR({
          ...currentParams,
          X: X,
          y: y
        });
      } else {
        setStatusMessage('❌ Невозможно обучить выбранную модель');
        setLoading(false);
        return;
      }

      setStatusMessage(
        `✅ Модель обучена! ` +
        `MAE: ${response.data.metrics?.MAE?.toFixed(4) || 'N/A'}, ` +
        `R²: ${response.data.metrics?.R2?.toFixed(4) || 'N/A'}`
      );
    } catch (error) {
      console.error('Ошибка обучения модели:', error);
      setStatusMessage(`❌ Ошибка обучения: ${error.response?.data?.detail || error.message}`);
    } finally {
      setLoading(false);
    }
  };

  // Запуск бэктеста
  const runBacktest = async () => {
    try {
      if (candles.length === 0) {
        setStatusMessage('❌ Нет данных для бэктеста');
        return;
      }

      setLoading(true);
      setStatusMessage('Запуск бэктеста...');

      const { X, y, prices } = prepareTrainingData(candles);
      const currentParams = modelParams[activeTab];

      const response = await backtestAPI.runBacktestWithModel({
        model_type: activeTab.toUpperCase(),
        model_params: currentParams,
        prices: prices,
        features: X
      });

      setBacktestResult(response.data);
      setStatusMessage(`✅ Бэктест завершен! ROI: ${(response.data.roi * 100).toFixed(2)}%`);
      
    } catch (error) {
      console.error('Ошибка бэктеста:', error);
      setStatusMessage(`❌ Ошибка бэктеста: ${error.response?.data?.detail || error.message}`);
    } finally {
      setLoading(false);
    }
  };

  // Обновление параметров модели
  const updateParam = (modelType, paramName, value) => {
    setModelParams(prev => ({
      ...prev,
      [modelType]: {
        ...prev[modelType],
        [paramName]: paramName === 'gamma' ? value : parseFloat(value)
      }
    }));
  };

  // Рендер поля ввода параметра
  const renderParameterInput = (param, modelType) => {
    const currentValue = modelParams[modelType][param.name];
    
    if (param.type === 'select') {
      return (
        <select
          value={currentValue}
          onChange={(e) => updateParam(modelType, param.name, e.target.value)}
          className={`w-full rounded-2xl px-4 py-3 focus:outline-none focus:ring-2 focus:border-transparent transition-all duration-300 ${
            isDark
              ? 'bg-gray-700 border-gray-600 text-white focus:ring-cyan-500'
              : 'border border-gray-300 focus:ring-blue-500'
          }`}
        >
          {param.options.map(option => (
            <option key={option} value={option}>{option}</option>
          ))}
        </select>
      );
    } else {
      return (
        <input
          type="number"
          value={currentValue}
          min={param.min}
          max={param.max}
          step={param.step}
          onChange={(e) => updateParam(modelType, param.name, e.target.value)}
          className={`w-full rounded-2xl px-4 py-3 focus:outline-none focus:ring-2 focus:border-transparent transition-all duration-300 ${
            isDark
              ? 'bg-gray-700 border-gray-600 text-white focus:ring-cyan-500'
              : 'border border-gray-300 focus:ring-blue-500'
          }`}
        />
      );
    }
  };

  return (
    <div className="space-y-6">
      <div className={`rounded-3xl p-8 text-white shadow-2xl ${
        isDark
          ? 'bg-gradient-to-r from-green-600 to-cyan-600'
          : 'bg-gradient-to-r from-blue-500 to-purple-600'
      }`}>
        <h1 className="text-3xl font-bold mb-2">AI Модели и Бэктестинг</h1>
        <p className={isDark ? 'text-cyan-100' : 'text-blue-100'}>
          Настройка моделей, обучение и тестирование торговых стратегий
        </p>
      </div>

      <div className="bg-white dark:bg-gray-800 rounded-3xl shadow-lg border border-gray-200 dark:border-gray-700 p-6">
        {/* Вкладки моделей */}
        <div className="flex space-x-4 mb-6">
          {Object.keys(modelConfigs).map((modelKey) => (
            <button
              key={modelKey}
              onClick={() => setActiveTab(modelKey)}
              className={`px-6 py-3 rounded-2xl font-semibold transition-all duration-300 ${
                activeTab === modelKey
                  ? isDark
                    ? 'bg-gradient-to-r from-green-500 to-cyan-500 text-white shadow-lg'
                    : 'bg-gradient-to-r from-blue-500 to-purple-500 text-white shadow-lg'
                  : 'bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-gray-600'
              }`}
            >
              {modelConfigs[modelKey].name}
            </button>
          ))}
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          {/* Конфигурация данных */}
          <div className="lg:col-span-1">
            <h3 className="text-lg font-semibold text-gray-800 dark:text-white mb-4">
              Настройка данных
            </h3>
            
            <div className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                  FIGI тикер
                </label>
                <select
                  value={figi}
                  onChange={(e) => setFigi(e.target.value)}
                  className={`w-full rounded-2xl px-4 py-3 focus:outline-none focus:ring-2 focus:border-transparent transition-all duration-300 ${
                    isDark
                      ? 'bg-gray-700 border-gray-600 text-white focus:ring-cyan-500'
                      : 'border border-gray-300 focus:ring-blue-500'
                  }`}
                >
                  {availableFigis.map(figi => (
                    <option key={figi.value} value={figi.value}>
                      {figi.label}
                    </option>
                  ))}
                </select>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                  Дата начала
                </label>
                <input
                  type="date"
                  value={startDate}
                  onChange={(e) => setStartDate(e.target.value)}
                  className={`w-full rounded-2xl px-4 py-3 focus:outline-none focus:ring-2 focus:border-transparent transition-all duration-300 ${
                    isDark
                      ? 'bg-gray-700 border-gray-600 text-white focus:ring-cyan-500'
                      : 'border border-gray-300 focus:ring-blue-500'
                  }`}
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                  Дата окончания
                </label>
                <input
                  type="date"
                  value={endDate}
                  onChange={(e) => setEndDate(e.target.value)}
                  className={`w-full rounded-2xl px-4 py-3 focus:outline-none focus:ring-2 focus:border-transparent transition-all duration-300 ${
                    isDark
                      ? 'bg-gray-700 border-gray-600 text-white focus:ring-cyan-500'
                      : 'border border-gray-300 focus:ring-blue-500'
                  }`}
                />
              </div>

              <button
                onClick={loadCandles}
                className={`w-full py-3 rounded-2xl font-semibold border transition-all duration-300 ${
                  isDark
                    ? 'border-cyan-500 text-cyan-500 hover:bg-cyan-500 hover:text-white'
                    : 'border-blue-500 text-blue-500 hover:bg-blue-500 hover:text-white'
                }`}
              >
                Загрузить данные
              </button>
            </div>

            {/* Конфигурация модели */}
            <h3 className="text-lg font-semibold text-gray-800 dark:text-white mt-6 mb-4">
              Конфигурация модели
            </h3>
            
            <div className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                  Тип ядра
                </label>
                <div className={`px-4 py-3 rounded-2xl ${
                  isDark ? 'bg-gray-700 text-white' : 'bg-gray-100 text-gray-700'
                }`}>
                  {modelConfigs[activeTab].kernel}
                </div>
              </div>

              {modelConfigs[activeTab].parameters.map((param) => (
                <div key={param.name}>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                    {param.name}
                  </label>
                  {renderParameterInput(param, activeTab)}
                </div>
              ))}
            </div>

            <div className="flex space-x-4 mt-6">
              <button
                onClick={trainModel}
                disabled={loading}
                className={`flex-1 py-3 rounded-2xl font-semibold text-white shadow-lg hover:shadow-xl transform hover:-translate-y-0.5 transition-all duration-300 ${
                  loading
                    ? 'bg-gray-400 cursor-not-allowed'
                    : isDark
                      ? 'bg-gradient-to-r from-green-600 to-cyan-600 hover:from-green-700 hover:to-cyan-700'
                      : 'bg-gradient-to-r from-blue-600 to-purple-600 hover:from-blue-700 hover:to-purple-700'
                }`}
              >
                {loading ? 'Обучение...' : 'Обучить модель'}
              </button>

              <button
                onClick={runBacktest}
                disabled={loading}
                className={`flex-1 py-3 rounded-2xl font-semibold border transition-all duration-300 ${
                  loading
                    ? 'border-gray-400 text-gray-400 cursor-not-allowed'
                    : isDark
                      ? 'border-yellow-500 text-yellow-500 hover:bg-yellow-500 hover:text-white'
                      : 'border-orange-500 text-orange-500 hover:bg-orange-500 hover:text-white'
                }`}
              >
                {loading ? 'Тестирование...' : 'Бэктест'}
              </button>
            </div>
          </div>

          {/* Результаты и данные */}
          <div className="lg:col-span-2">
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
              {/* Результаты бэктеста */}
              {backtestResult && (
                <div className="lg:col-span-2">
                  <h3 className="text-lg font-semibold text-gray-800 dark:text-white mb-4">
                    Результаты бэктеста
                  </h3>
                  <div className={`rounded-2xl p-6 ${
                    isDark ? 'bg-gray-700' : 'bg-gray-100'
                  }`}>
                    <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                      <div className="text-center">
                        <div className="text-2xl font-bold text-green-500">
                          {(backtestResult.roi * 100).toFixed(2)}%
                        </div>
                        <div className="text-sm text-gray-600 dark:text-gray-400">ROI</div>
                      </div>
                      <div className="text-center">
                        <div className="text-2xl font-bold text-blue-500">
                          {backtestResult.final_balance?.toFixed(2) || 'N/A'}
                        </div>
                        <div className="text-sm text-gray-600 dark:text-gray-400">Финальный баланс</div>
                      </div>
                      <div className="text-center">
                        <div className="text-2xl font-bold text-purple-500">
                          {backtestResult.total_trades || 0}
                        </div>
                        <div className="text-sm text-gray-600 dark:text-gray-400">Всего сделок</div>
                      </div>
                      <div className="text-center">
                        <div className="text-2xl font-bold text-orange-500">
                          {candles.length}
                        </div>
                        <div className="text-sm text-gray-600 dark:text-gray-400">Свечей проанализировано</div>
                      </div>
                    </div>
                  </div>
                </div>
              )}

              {/* Статус */}
              {statusMessage && (
                <div className="lg:col-span-2">
                  <div className={`p-4 rounded-xl ${
                    statusMessage.includes('❌')
                      ? 'bg-red-100 text-red-700 dark:bg-red-900 dark:text-red-200'
                      : statusMessage.includes('✅')
                      ? 'bg-green-100 text-green-700 dark:bg-green-900 dark:text-green-200'
                      : 'bg-blue-100 text-blue-700 dark:bg-blue-900 dark:text-blue-200'
                  }`}>
                    {statusMessage}
                  </div>
                </div>
              )}

              {/* Исторические данные */}
              <div className="lg:col-span-2">
                <h3 className="text-lg font-semibold text-gray-800 dark:text-white mb-4">
                  Исторические данные
                </h3>
                <div className="flex justify-between items-center mb-4">
                  <span className="text-sm text-gray-600 dark:text-gray-400">
                    Загружено свечей: {candles.length}
                  </span>
                  <span className="text-sm text-gray-600 dark:text-gray-400">
                    Период: {startDate} - {endDate}
                  </span>
                </div>
                <div className={`rounded-2xl p-6 overflow-auto max-h-96 ${
                  isDark ? 'bg-gray-700' : 'bg-gray-100'
                }`}>
                  {candles.length > 0 ? (
                    <table className="w-full text-sm text-left text-gray-800 dark:text-gray-200">
                      <thead>
                        <tr className="border-b border-gray-300 dark:border-gray-600">
                          <th className="pb-2">Time</th>
                          <th className="pb-2">Open</th>
                          <th className="pb-2">High</th>
                          <th className="pb-2">Low</th>
                          <th className="pb-2">Close</th>
                          <th className="pb-2">Volume</th>
                        </tr>
                      </thead>
                      <tbody>
                        {candles.slice(0, 15).map((c, idx) => (
                          <tr key={idx} className="border-b border-gray-300 dark:border-gray-600">
                            <td className="py-2">{new Date(c.time).toLocaleDateString()}</td>
                            <td className="py-2">{parseFloat(c.o).toFixed(4)}</td>
                            <td className="py-2">{parseFloat(c.h).toFixed(4)}</td>
                            <td className="py-2">{parseFloat(c.l).toFixed(4)}</td>
                            <td className="py-2">{parseFloat(c.c).toFixed(4)}</td>
                            <td className="py-2">{parseInt(c.v).toLocaleString()}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  ) : (
                    <p className="text-gray-500 dark:text-gray-400 text-center py-4">
                      Нет данных. Нажмите "Загрузить данные" для загрузки.
                    </p>
                  )}
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
